CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 SELECT COALESCE((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin', false)
$function$
;

CREATE OR REPLACE FUNCTION public.market_admin_update_purchase(p_request uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old text;
begin
 if not public.is_admin() then raise exception 'Admin only' using errcode='42501';end if;
 if p_status not in ('cancelled','awaiting_payment_setup','disputed') then
  raise exception 'This preview does not activate payment processing or payouts' using errcode='22023';
 end if;
 if char_length(coalesce(p_note,''))>500 then raise exception 'Note too long' using errcode='22023';end if;
 select status into v_old from public.market_purchase_requests where id=p_request for update;
 if v_old is null then raise exception 'Request not found' using errcode='P0002';end if;
 if v_old not in ('requested','awaiting_payment_setup','disputed') then
   raise exception 'This request cannot be changed in preview' using errcode='23514';
 end if;
 update public.market_purchase_requests
 set status=p_status,admin_note=nullif(trim(p_note),''),
     updated_at=now() where id=p_request;
end
$function$
;

CREATE OR REPLACE FUNCTION public.market_browse()
 RETURNS TABLE(id bigint, title text, platform text, description text, price numeric, image_url text, is_pro boolean, submitted_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
select l.id,l.title,l.platform,l.description,l.price,l.image_url,coalesce(p.is_pro and (p.pro_until is null or p.pro_until>now()),false) as is_pro,l.submitted_at
from public.market_listings l left join public.seller_profiles p on p.user_id=l.seller_id
where l.status='approved'
order by is_pro desc,l.submitted_at desc limit 100 $function$
;

CREATE OR REPLACE FUNCTION public.market_inbox()
 RETURNS TABLE(id bigint, listing_id bigint, listing_title text, seller_id uuid, buyer_id uuid, created_at timestamp with time zone, last_message_at timestamp with time zone, last_message_preview text, last_sender_id uuid, unread_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select c.id,
         c.listing_id,
         coalesce(l.title, 'Listing #' || c.listing_id::text) as listing_title,
         c.seller_id, c.buyer_id, c.created_at,
         latest.created_at as last_message_at,
         left(latest.body, 180) as last_message_preview,
         latest.sender_id as last_sender_id,
         (
           select count(*)
           from public.market_messages m
           where m.conversation_id = c.id
             and m.sender_id <> auth.uid()
             and m.created_at > coalesce(read_state.last_read_at, 'epoch'::timestamptz)
         ) as unread_count
  from public.market_conversations c
  left join public.market_listings l on l.id = c.listing_id
  left join public.market_conversation_reads read_state
    on read_state.conversation_id = c.id and read_state.user_id = auth.uid()
  left join lateral (
    select m.body, m.created_at, m.sender_id
    from public.market_messages m
    where m.conversation_id = c.id
    order by m.created_at desc, m.id desc
    limit 1
  ) latest on true
  where auth.uid() is not null
    and (c.buyer_id = auth.uid() or c.seller_id = auth.uid())
  order by coalesce(latest.created_at, c.created_at) desc, c.id desc
  limit 100
$function$
;

CREATE OR REPLACE FUNCTION public.market_mark_read(p_conversation bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'Sign in required' using errcode = '28000';
  end if;
  if not exists (
    select 1 from public.market_conversations c
    where c.id = p_conversation and (c.buyer_id = v_user or c.seller_id = v_user)
  ) then
    raise exception 'Conversation unavailable' using errcode = '42501';
  end if;

  insert into public.market_conversation_reads (conversation_id, user_id, last_read_at)
    values (p_conversation, v_user, now())
  on conflict (conversation_id, user_id)
    do update set last_read_at = greatest(
      public.market_conversation_reads.last_read_at, excluded.last_read_at
    );
end
$function$
;

CREATE OR REPLACE FUNCTION public.market_remove_listing(p_listing bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_actor uuid:=auth.uid();v_seller uuid;v_status text;v_admin boolean;
begin
 if v_actor is null then raise exception 'Sign in required' using errcode='28000';end if;
 v_admin:=public.is_admin();
 select seller_id,status into v_seller,v_status
 from public.market_listings where id=p_listing for update;
 if v_seller is null then raise exception 'Listing not found' using errcode='P0002';end if;
 if v_seller<>v_actor and not v_admin then raise exception 'Not authorized' using errcode='42501';end if;
 if v_status='removed' then return;end if;
 if exists(select 1 from public.market_purchase_requests p
   where p.listing_id=p_listing and p.status in
   ('payment_reported','payment_verified','delivery_reported','disputed')) then
   raise exception 'Listing has an active payment/delivery review. Contact an administrator before removal'
     using errcode='23514';
 end if;
 update public.market_listings set status='removed' where id=p_listing;
 insert into public.market_listing_activity(listing_id,actor_id,previous_status,action)
 values(p_listing,v_actor,v_status,case when v_admin and v_actor<>v_seller
   then 'removed_by_admin' else 'removed_by_seller' end);
end
$function$
;

CREATE OR REPLACE FUNCTION public.market_request_purchase(p_listing bigint, p_method text DEFAULT 'CONTACT_SUPPORT'::text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_buyer uuid := auth.uid();
  v_seller uuid;
  v_title text;
  v_price numeric;
  v_id uuid;
  v_method text := upper(trim(coalesce(p_method, '')));
BEGIN
  IF v_buyer IS NULL THEN
    RAISE EXCEPTION 'Sign in required' USING errcode = '28000';
  END IF;
  IF v_method NOT IN ('LTC', 'BTC', 'BANK', 'CONTACT_SUPPORT') THEN
    RAISE EXCEPTION 'Invalid payment preference' USING errcode = '22023';
  END IF;
  IF char_length(coalesce(p_note, '')) > 500 THEN
    RAISE EXCEPTION 'Note too long' USING errcode = '22023';
  END IF;

  -- No checkout: only approved listings may receive a review request.
  SELECT seller_id, title, price INTO v_seller, v_title, v_price
  FROM public.market_listings
  WHERE id = p_listing AND status = 'approved';

  IF v_seller IS NULL THEN
    RAISE EXCEPTION 'Listing is not currently available' USING errcode = '23514';
  END IF;
  IF v_seller = v_buyer THEN
    RAISE EXCEPTION 'Cannot purchase your own listing' USING errcode = '23514';
  END IF;

  -- Serialize concurrent requests for the same buyer/listing, across tabs and devices.
  -- Locks are transaction-scoped and release automatically on commit/rollback.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext(v_buyer::text),
    pg_catalog.hashtext(p_listing::text)
  );

  SELECT id INTO v_id
  FROM public.market_purchase_requests
  WHERE listing_id = p_listing
    AND buyer_id = v_buyer
    AND status NOT IN ('cancelled', 'completed', 'seller_payout_recorded')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  INSERT INTO public.market_purchase_requests
    (listing_id, buyer_id, seller_id, listing_title, price_usd,
     payment_method, buyer_note, status)
  VALUES
    (p_listing, v_buyer, v_seller, v_title, v_price,
     v_method, nullif(trim(p_note), ''), 'requested')
  RETURNING id INTO v_id;

  RETURN v_id;
END
$function$
;

CREATE OR REPLACE FUNCTION public.market_require_uploaded_photo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.status = 'approved'
   and old.status is distinct from 'approved'
   and not exists(
     select 1
     from public.market_listing_media m
     join storage.objects obj on obj.bucket_id = 'market-gallery'
                             and obj.name = m.object_path
     where m.listing_id = new.id
       and m.seller_id = new.seller_id
   )
 then
   raise exception 'At least one uploaded gallery photo is required before approval'
     using errcode = '23514';
 end if;
 return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.market_send_message(p_conversation bigint, p_body text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_sender uuid:=auth.uid();v_id bigint;begin
if v_sender is null then raise exception 'Sign in required';end if;
if char_length(trim(coalesce(p_body,''))) not between 1 and 2000 then raise exception 'Invalid message';end if;
if not exists(select 1 from public.market_conversations where id=p_conversation and (seller_id=v_sender or buyer_id=v_sender)) then raise exception 'Conversation unavailable';end if;
insert into public.market_messages(conversation_id,sender_id,body) values(p_conversation,v_sender,trim(p_body)) returning id into v_id;return v_id;end $function$
;

CREATE OR REPLACE FUNCTION public.market_set_pro(p_user uuid, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
if not public.is_admin() then raise exception 'Admin only';end if;
insert into public.seller_profiles(user_id,display_name,is_pro,pro_until) values(p_user,'Seller',p_enabled,null)
on conflict(user_id) do update set is_pro=excluded.is_pro,pro_until=null;
end $function$
;

CREATE OR REPLACE FUNCTION public.market_start_chat(p_listing bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_buyer uuid:=auth.uid();v_seller uuid;v_id bigint;begin
if v_buyer is null then raise exception 'Sign in required';end if;
select seller_id into v_seller from public.market_listings where id=p_listing and status='approved';
if v_seller is null then raise exception 'Listing unavailable';end if;
if v_buyer=v_seller then raise exception 'Cannot message yourself';end if;
insert into public.market_conversations(listing_id,seller_id,buyer_id) values(p_listing,v_seller,v_buyer) on conflict(listing_id,buyer_id) do update set listing_id=excluded.listing_id returning id into v_id;
return v_id;end $function$
;

CREATE OR REPLACE FUNCTION public.market_submit(p_title text, p_platform text, p_description text, p_price numeric, p_image_url text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_id bigint;
  v_pro boolean;
  v_today_count integer;
begin
  if v_user is null then
    raise exception 'Sign in first' using errcode = '28000';
  end if;

  if char_length(trim(coalesce(p_title, ''))) not between 5 and 120
     or char_length(trim(coalesce(p_description, ''))) not between 20 and 3000
     or char_length(trim(coalesce(p_platform, ''))) not between 2 and 50
     or p_price is null or p_price < 1 or p_price > 1000000 then
    raise exception 'Invalid listing details' using errcode = '22023';
  end if;

  -- Prevent concurrent browser tabs from racing the same daily limit.
  perform pg_advisory_xact_lock(hashtext(v_user::text));
  select (is_pro and (pro_until is null or pro_until > now()))
  into v_pro
  from public.seller_profiles
  where user_id = v_user;

  if not coalesce(v_pro, false) then
    select count(*)::integer into v_today_count
    from public.market_listings
    where seller_id = v_user
      and submitted_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc'
      and submitted_at < (date_trunc('day', now() at time zone 'utc') + interval '1 day') at time zone 'utc';

    if v_today_count >= 3 then
      raise exception 'Daily free listing limit reached (3 listings per UTC day)'
        using errcode = 'P0001';
    end if;
  end if;

  insert into public.market_listings
    (seller_id, title, platform, description, price, image_url)
  values
    (v_user, trim(p_title), trim(p_platform), trim(p_description), p_price,
     nullif(trim(coalesce(p_image_url, '')), ''))
  returning id into v_id;

  return v_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.market_submit_txid(p_request uuid, p_txid text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_buyer uuid:=auth.uid();v_status text;v_method text;v_id uuid;v_clean text;
BEGIN
 IF v_buyer IS NULL THEN RAISE EXCEPTION 'Sign in required' USING errcode='28000'; END IF;
 v_clean:=lower(trim(coalesce(p_txid,'')));
 IF v_clean !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'A 64-character hexadecimal transaction ID is required' USING errcode='22023';
 END IF;
 SELECT status,payment_method INTO v_status,v_method
 FROM public.market_purchase_requests WHERE id=p_request AND buyer_id=v_buyer FOR UPDATE;
 IF v_status IS NULL THEN RAISE EXCEPTION 'Purchase request unavailable' USING errcode='42501'; END IF;
 IF v_method NOT IN ('BTC','LTC') THEN
  RAISE EXCEPTION 'Transaction IDs can only be submitted for BTC or LTC review requests' USING errcode='22023';
 END IF;
 IF v_status NOT IN ('requested','awaiting_payment_setup','disputed') THEN
  RAISE EXCEPTION 'This request is not accepting transaction references' USING errcode='23514';
 END IF;
 IF EXISTS (SELECT 1 FROM public.market_txid_claims WHERE request_id=p_request) THEN
  RAISE EXCEPTION 'A transaction reference was already submitted for this request' USING errcode='23505';
 END IF;
 BEGIN
  INSERT INTO public.market_txid_claims(request_id,buyer_id,network,txid)
  VALUES (p_request,v_buyer,v_method,v_clean) RETURNING id INTO v_id;
 EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'This transaction reference is already registered on another request or has been submitted before' USING errcode='23505';
 END;
 -- No purchase status update; no listing mutation; no verification or payout.
 INSERT INTO public.market_notifications(recipient_id,kind,title,request_id)
 VALUES (v_buyer,'purchase_updated','Transaction ID received for review — NOT payment verification',p_request);
 INSERT INTO public.market_notifications(for_admin,kind,title,request_id)
 VALUES (true,'purchase_updated','Unverified transaction ID submitted for review',p_request);
 RETURN v_id;
END $function$
;

CREATE OR REPLACE FUNCTION public.refresh_product_sales_snapshots()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare affected integer;
begin
 if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required' using errcode='42501';end if;
 insert into public.product_sales_snapshots(product_id,units_sold)
 select p.id,coalesce(s.units_sold,0)
 from public.products p left join (
  select line->>'id' as product_id,sum((line->>'qty')::bigint) as units_sold
  from public.tc42_orders o
  cross join lateral jsonb_array_elements(case when jsonb_typeof(o.items)='array' then o.items else '[]'::jsonb end) line
  where o.status in ('paid','fulfilled') and (line->>'qty') ~ '^[1-9][0-9]{0,5}$'
  group by line->>'id'
 ) s on s.product_id=p.id::text
 on conflict(product_id) do update set units_sold=excluded.units_sold,updated_at=now();
 get diagnostics affected=row_count;
 return affected;
end;$function$
;

CREATE OR REPLACE FUNCTION public.store_issue_crypto(p_user uuid, p_order uuid, p_network text, p_address text, p_rate numeric)
 RETURNS store_crypto_invoice
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o public.tc42_orders; i public.store_crypto_invoice; base bigint; discount int;
begin
 select * into strict o from public.tc42_orders where id=p_order and customer_id=p_user for update;
 if o.status <> 'awaiting_payment' then raise exception 'Order unavailable'; end if;
 select * into i from public.store_crypto_invoice where order_id=p_order;
 if found then
   if i.network<>p_network or i.expires_at<=now() then raise exception 'Use a new order for a different or expired quote'; end if;
   return i;
 end if;
 if p_rate<=0 or p_rate is null or o.total_amount<=0 then raise exception 'Invalid quote'; end if;
 base:=ceil(o.total_amount*100000000/p_rate);
 if base<1000 then raise exception 'Amount below invoice minimum'; end if;
 -- Never reuse an amount at this shared destination, even after expiration.
 -- Resolve collisions with a discount capped at 0.25 percent.
 for discount in 0..least(255, floor(base*0.0025),base-1000)::int loop
   insert into public.store_crypto_invoice(order_id,network,address,units)
   values(p_order,p_network,p_address,base-discount)
   on conflict(network,address,units) do nothing returning * into i;
   if found then return i; end if;
 end loop;
 raise exception 'No distinct quote available';
end $function$
;

CREATE OR REPLACE FUNCTION public.store_reserve_txid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.txid is not null and (tg_op='INSERT' or old.txid is distinct from new.txid) then
   insert into public.store_used_txid values(lower(new.txid));
 end if;
 return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.store_settle_crypto(p_user uuid, p_order uuid, p_txid text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o public.tc42_orders; i public.store_crypto_invoice; item record; enough boolean:=true; result text;
begin
 select * into strict o from public.tc42_orders where id=p_order and customer_id=p_user for update;
 select * into strict i from public.store_crypto_invoice where order_id=p_order for update;
 if i.txid=p_txid then return o.status; end if;
 if i.txid is not null or o.status<>'awaiting_payment' then raise exception 'Order already processed'; end if;
 if exists(select 1 from public.market_txid_claims where txid=p_txid) then raise exception 'TXID already claimed'; end if;
 for item in select * from jsonb_to_recordset(o.items) as x(id bigint,qty int) order by id loop
   perform 1 from public.products where id=item.id and status='available' and stock>=item.qty for update;
   if not found then enough:=false; end if;
 end loop;
 if enough then
   update public.products p set stock=p.stock-x.qty from jsonb_to_recordset(o.items) as x(id bigint,qty int) where p.id=x.id;
 end if;
 result:=case when enough then 'paid' else 'payment_review' end;
 update public.store_crypto_invoice set txid=p_txid where order_id=p_order;
 update public.tc42_orders set status=result where id=p_order;
 return result;
end $function$
;

CREATE OR REPLACE FUNCTION public.tc34_notify_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_buyer uuid; v_seller uuid;
BEGIN
 SELECT buyer_id,seller_id INTO v_buyer,v_seller
 FROM public.market_conversations WHERE id=NEW.conversation_id;
 IF v_buyer IS NULL OR v_seller IS NULL THEN RETURN NULL; END IF;
 INSERT INTO public.market_notifications(recipient_id,kind,title,conversation_id)
 VALUES (CASE WHEN NEW.sender_id=v_buyer THEN v_seller ELSE v_buyer END,
         'message','New marketplace message',NEW.conversation_id);
 INSERT INTO public.market_notifications(for_admin,kind,title,conversation_id)
 VALUES (true,'message','New marketplace conversation message',NEW.conversation_id);
 RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.tc34_notify_purchase()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP = 'INSERT' THEN
  INSERT INTO public.market_notifications (recipient_id,kind,title,listing_id,request_id)
   VALUES (NEW.seller_id,'purchase_requested','New purchase review request',NEW.listing_id,NEW.id);
  INSERT INTO public.market_notifications (for_admin,kind,title,listing_id,request_id)
   VALUES (true,'purchase_requested','New marketplace purchase request',NEW.listing_id,NEW.id);
 ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
  INSERT INTO public.market_notifications (recipient_id,kind,title,listing_id,request_id)
   VALUES (NEW.buyer_id,'purchase_updated','Purchase request status changed',NEW.listing_id,NEW.id),
          (NEW.seller_id,'purchase_updated','Purchase request status changed',NEW.listing_id,NEW.id);
 END IF;
 RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.tc35_queue_opted_in_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NEW.recipient_id IS NOT NULL THEN
  INSERT INTO public.market_email_outbox(notification_id,user_id)
  SELECT NEW.id,NEW.recipient_id
  WHERE EXISTS(SELECT 1 FROM public.market_alert_preferences
    WHERE user_id=NEW.recipient_id AND email_enabled);
 ELSIF NEW.for_admin THEN
  INSERT INTO public.market_email_outbox(notification_id,user_id)
  SELECT NEW.id,u.id FROM auth.users u
  JOIN public.market_alert_preferences p ON p.user_id=u.id AND p.email_enabled
  WHERE u.raw_app_meta_data->>'role'='admin'
  ON CONFLICT DO NOTHING;
 END IF;
 RETURN NULL;
END $function$
;

CREATE OR REPLACE FUNCTION public.tc42_create_order(p_items jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_user uuid := auth.uid(); v_entry jsonb; v_product record; v_id bigint; v_qty int; v_total numeric(12,2):=0; v_lines jsonb:='[]'::jsonb; v_order uuid;
BEGIN
 IF v_user IS NULL THEN RAISE EXCEPTION 'Sign in to save an order'; END IF;
 IF jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid cart size'; END IF;
 FOR v_entry IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  IF jsonb_typeof(v_entry)<>'object' OR (v_entry->>'id') !~ '^[0-9]{1,18}$' OR (v_entry->>'qty') !~ '^[0-9]{1,5}$' THEN RAISE EXCEPTION 'Invalid cart item'; END IF;
  v_id:=(v_entry->>'id')::bigint; v_qty:=(v_entry->>'qty')::int;
  IF v_qty<1 THEN RAISE EXCEPTION 'Invalid quantity'; END IF;
  SELECT id,title,price,stock,status,min_qty,max_qty INTO v_product FROM public.products WHERE id=v_id FOR SHARE;
  IF NOT FOUND OR v_product.status IS DISTINCT FROM 'available' OR v_product.stock<v_qty THEN RAISE EXCEPTION 'Product unavailable'; END IF;
  IF v_qty<v_product.min_qty OR (v_product.max_qty IS NOT NULL AND v_qty>v_product.max_qty) THEN RAISE EXCEPTION 'Quantity outside allowed range'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_lines) x WHERE (x->>'id')::bigint=v_id) THEN RAISE EXCEPTION 'Duplicate product'; END IF;
  v_total:=v_total+round(v_product.price*v_qty,2);
  IF v_total>9999999999 THEN RAISE EXCEPTION 'Cart total too large'; END IF;
  v_lines:=v_lines||jsonb_build_array(jsonb_build_object('id',v_id,'title',v_product.title,'unit_price',v_product.price,'qty',v_qty));
 END LOOP;
 INSERT INTO public.tc42_orders(customer_id,total_amount,items) VALUES(v_user,v_total,v_lines) RETURNING id INTO v_order;
 RETURN v_order;
END;$function$
;

