CREATE POLICY "Admins insert products" ON public."products" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (( SELECT is_admin() AS is_admin));

CREATE POLICY "Admins update products" ON public."products" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (( SELECT is_admin() AS is_admin)) WITH CHECK (( SELECT is_admin() AS is_admin));

CREATE POLICY "Admins delete products" ON public."products" AS PERMISSIVE FOR DELETE TO "authenticated" USING (( SELECT is_admin() AS is_admin));

CREATE POLICY "Public reads available products" ON public."products" AS PERMISSIVE FOR SELECT TO "anon" USING ((status = 'available'::text));

CREATE POLICY "Users read available or admins read all" ON public."products" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((status = 'available'::text) OR ( SELECT is_admin() AS is_admin)));

CREATE POLICY "Read own orders or admin" ON public."orders" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((user_id = ( SELECT auth.uid() AS uid)) OR ( SELECT is_admin() AS is_admin)));

CREATE POLICY "Read own order items or admin" ON public."order_items" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM orders o
  WHERE ((o.id = order_items.order_id) AND ((o.user_id = ( SELECT auth.uid() AS uid)) OR ( SELECT is_admin() AS is_admin))))));

CREATE POLICY "Read own tickets or admin" ON public."support_tickets" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((user_id = ( SELECT auth.uid() AS uid)) OR ( SELECT is_admin() AS is_admin)));

