CREATE POLICY "Thread read" ON public."tc42_support_threads" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((customer_id = ( SELECT auth.uid() AS uid)) OR ( SELECT is_admin() AS is_admin)));

