CREATE POLICY "Message read" ON public."tc42_support_messages" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM tc42_support_threads t
  WHERE ((t.id = tc42_support_messages.thread_id) AND ((t.customer_id = ( SELECT auth.uid() AS uid)) OR ( SELECT is_admin() AS is_admin))))));

